        let mid = &name[1..name.len() - 4];
        if let Ok(d) = mid.parse::<i32>() {
            v.push((d, ent.path().to_string_lossy().into_owned()));
        }
    }
    v.sort_by_key(|x| x.0);
    v
}

pub fn nlines(path: &str) -> i32 {
    match fs::read_to_string(path) {
        Ok(t) => t.lines().filter(|l| !l.trim().is_empty()).count() as i32,
