use std::fs;

fn rows(text: &str) -> i32 {
    text.lines().filter(|line| !line.trim().is_empty()).count() as i32
}

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let tpl = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let out = tpl
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", out).map_err(|_| 1)
}

pub fn gait(taken: i32, packed: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    let mut matched = 0;
    let mut probe = String::new();

    for (day, _) in packed {
        let name = format!("d{:08}.tbl", day);
        let original_path = format!("/app/daywell/{}", name);
        let restored_path = format!("/app/packbay/latest/{}", name);

        // These reads are deliberately independent of ledger.json and staging.
        let original = match fs::read_to_string(&original_path) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        let restored = match fs::read_to_string(&restored_path) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        let count = rows(&original);
        if original != restored || count != rows(&restored) {
            return 1;
        }
        matched += count;
        if count > 0 {
            probe = original_path;
        }
    }

    if probe.is_empty() || matched != taken {
        return 1;
    }
    if emit(&probe, matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
